import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    M = max(a) + 1
    spf = list(range(M))
    i = 2
    while i * i < M:
        if spf[i] == i:
            for j in range(i * i, M, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    om = [0] * M
    for k in range(2, M):
        om[k] = om[k // spf[k]] + 1
    x = 0
    for v in a:
        x ^= om[v]
    print("Anna" if x != 0 else "Bruno")

