class Solution:
    def maxSubarrays(self, n, conflictingPairs):
        m = len(conflictingPairs)
        byb = [[] for _ in range(n + 1)]
        for j, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            byb[b].append((a, j))
        gain = [0] * m
        m1v = 0; m1i = -1; m2v = 0
        base = 0
        for r in range(1, n + 1):
            for a, j in byb[r]:
                if a > m1v:
                    m2v = m1v
                    m1v = a
                    m1i = j
                elif a > m2v:
                    m2v = a
            base += r - m1v
            if m1i >= 0:
                gain[m1i] += m1v - m2v
        return base + max(gain)

