import sys, itertools, bisect

def lis(s):
    t = []
    for x in s:
        i = bisect.bisect_left(t, x)
        if i == len(t):
            t.append(x)
        else:
            t[i] = x
    return len(t)

def lds(s):
    return lis([-x for x in s])

def solve(A, B, M):
    N = A * B - 1
    cnt = 0
    for p in itertools.permutations(range(1, N + 1)):
        p = list(p)
        if lis(p) != A or lds(p) != B:
            continue
        ok = False
        for n in range(0, N + 1):
            q = p + [n + 0.5]
            if lis(q) == A and lds(q) == B:
                ok = True
                break
        if ok:
            cnt += 1
    return cnt % M

