import sys
from functools import lru_cache
sys.setrecursionlimit(10000)
def solve(boxes, M, D=14):
    # boxes: list of (V,P)
    def canon(types):
        return tuple(sorted(tuple(sorted(t)) for t in types))
    @lru_cache(maxsize=None)
    def f(state, d):
        if d == 0: return 0
        best = None
        seen=set()
        for ti, t in enumerate(state):
            if t in seen: continue
            seen.add(t)
            opts = [0]
            for bi,(bidx,rem) in enumerate(t):
                nt = list(t)
                if rem-1>0: nt[bi]=(bidx,rem-1)
                else: nt.pop(bi)
                ns = list(state); ns[ti]=tuple(sorted(nt))
                opts.append(1+f(canon(ns), d-1))
            for i,(V,P) in enumerate(boxes):
                if V-1>0: nt = tuple(sorted(t+((i,V-1),)))
                else: nt = t
                ns=list(state); ns[ti]=nt
                opts.append(1-P+f(canon(ns), d-1))
            v = max(opts)
            if best is None or v<best: best=v
        return best
    init = canon([()]*M)
    res=[]
    for d in range(1,D+1):
        f.cache_clear()
        res.append(f(init,d))
    return res
