class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        steps = [0] * (L + 2)
        for c in range(2, L + 2):
            steps[c] = 1 + steps[bin(c).count('1')]
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for a in range(N + 1):
            C[a][0] = 1
            for b in range(1, a + 1):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD
        total = 0
        for c in range(1, L + 1):
            if steps[c] > k - 1:
                continue
            cnt = 0
            res = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    m = L - i - 1
                    need = c - cnt
                    if 0 <= need <= m:
                        res += C[m][need]
                    cnt += 1
            total += res
        return total % MOD

