def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    rows = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u
    rank = 0
    pivcol = []
    for col in range(n):
        sel = -1
        for r in range(rank, n):
            if (rows[r] >> col) & 1:
                sel = r
                break
        if sel == -1:
            continue
        rows[rank], rows[sel] = rows[sel], rows[rank]
        for i in range(n):
            if i != rank and (rows[i] >> col) & 1:
                rows[i] ^= rows[rank]
        pivcol.append(col)
        rank += 1
    pivset = set(pivcol)
    free = [c for c in range(n) if c not in pivset]
    basis = []
    for f in free:
        x = 1 << f
        for i in range(rank):
            if (rows[i] >> f) & 1:
                x |= 1 << pivcol[i]
        basis.append(x)
    X = [0] * n
    for j, b in enumerate(basis):
        for v in range(n):
            if (b >> v) & 1:
                X[v] |= 1 << j
    if any(x == 0 for x in X):
        print("No")
        return
    print("Yes")
    print(" ".join(map(str, X)))

