from bisect import bisect_left, bisect_right
def sol(n,s,qs):
    P1=[0]*(n+1); P2=[0]*(n+1); sl=[]
    for i in range(1,n+1):
        c=s[i-1]; P1[i]=P1[i-1]+(c=='1'); P2[i]=P2[i-1]+(c=='2')
        if c=='/': sl.append(i)
    out=[]
    for L,R in qs:
        lo=bisect_left(sl,L); hi=bisect_right(sl,R)
        if lo>=hi: out.append(0); continue
        PR2=P2[R]; base1=P1[L-1]; a=lo; b=hi
        while a<b:
            m=(a+b)//2; p=sl[m]
            if P1[p-1]-base1>=PR2-P2[p]: b=m
            else: a=m+1
        best=0
        if a<hi: best=max(best,PR2-P2[sl[a]])
        if a-1>=lo: best=max(best,P1[sl[a]-1]-base1 if False else P1[sl[a-1]-1]-base1)
        out.append(2*best+1)
    return out
def brute(s,L,R):
    t=s[L-1:R]; best=0
    for i,c in enumerate(t):
        if c=='/':
            a=t[:i].count('1'); b=t[i+1:].count('2'); best=max(best,2*min(a,b)+1)
    return best
