from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        nxt = {1: 2, 2: 0, 0: 2}
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        S = []
        P = []
        for di, dj in dirs:
            s = [[0] * m for _ in range(n)]
            p = [[0] * m for _ in range(n)]
            rows_s = range(n - 1, -1, -1) if di == 1 else range(n)
            cols_s = range(m - 1, -1, -1) if dj == 1 else range(m)
            for i in rows_s:
                gi = grid[i]; si = s[i]
                for j in cols_s:
                    v = gi[j]
                    ni = i + di; nj = j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt[v]:
                        si[j] = 1 + s[ni][nj]
                    else:
                        si[j] = 1
            rows_p = range(n) if di == 1 else range(n - 1, -1, -1)
            cols_p = range(m) if dj == 1 else range(m - 1, -1, -1)
            for i in rows_p:
                gi = grid[i]; pi = p[i]
                for j in cols_p:
                    v = gi[j]
                    if v == 1:
                        pi[j] = 1
                    else:
                        pi_i = i - di; pj = j - dj
                        if 0 <= pi_i < n and 0 <= pj < m and p[pi_i][pj] > 0 and nxt[grid[pi_i][pj]] == v:
                            pi[j] = p[pi_i][pj] + 1
                        else:
                            pi[j] = 0
            S.append(s); P.append(p)
        ans = 0
        for i in range(n):
            for j in range(m):
                for d in range(4):
                    pv = P[d][i][j]
                    if pv == 0:
                        continue
                    if pv > ans:
                        ans = pv
                    d2 = (d + 1) % 4
                    sv = S[d2][i][j]
                    if sv > 0 and pv + sv - 1 > ans:
                        ans = pv + sv - 1
        return ans

