class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        K = 1 << k
        sh = [[0] * K for _ in range(k)]
        for x in range(k):
            for M in range(K):
                res = 0
                for r in range(k):
                    if M >> r & 1:
                        res |= 1 << ((r + x) % k)
                sh[x][M] = res
        p = [0] * n
        p[0] = 1 % k
        for t in range(1, n):
            p[t] = p[t - 1] * 10 % k
        W = []
        Xs = []
        cache = {}
        for i in range(m):
            j = n - 1 - i
            wi = (p[i] + p[j]) % k if i != j else p[i] % k
            lo = 1 if i == 0 else 0
            key = (wi, lo)
            if key not in cache:
                cache[key] = sorted({(d * wi) % k for d in range(lo, 10)})
            W.append(wi)
            Xs.append(cache[key])
        good = [0] * (m + 1)
        good[m] = 1
        for i in range(m - 1, -1, -1):
            g = 0
            nxt = good[i + 1]
            for x in Xs[i]:
                g |= sh[x][nxt]
            good[i] = g
        if not (good[0] & 1):
            return ""
        r = 0
        digs = []
        for i in range(m):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (r - d * W[i]) % k
                if good[i + 1] >> nr & 1:
                    digs.append(chr(48 + d))
                    r = nr
                    break
        s = ''.join(digs)
        if n % 2 == 0:
            return s + s[::-1]
        return s + s[-2::-1]

