class Solution:
    def makeStringGood(self, s: str) -> int:
        INF = float('inf')
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        best = n
        for f in range(1, min(n, max(cnt) + 1) + 1):
            dp = [INF] * (f + 1)
            dp[0] = 0
            for i in range(26):
                k = cnt[i]
                new = [INF] * (f + 1)
                m = INF
                for c in range(f + 1):
                    if dp[c] < INF:
                        v = dp[c] + k + c
                        if v < m:
                            m = v
                g = [INF] * (f + 2)
                for c in range(f + 1):
                    if dp[c] < INF:
                        T = k + c
                        if T < f:
                            v = dp[c] + f - T
                            if v < m:
                                m = v
                        else:
                            g[c] = dp[c] + T - f
                new[0] = m
                suffix = [INF] * (f + 2)
                suf = INF
                for j in range(f, -1, -1):
                    if g[j] < suf:
                        suf = g[j]
                    suffix[j] = suf
                for x in range(1, f + 1):
                    j = f - k + x
                    if j > f:
                        continue
                    if j < 0:
                        j = 0
                    if suffix[j] < new[x]:
                        new[x] = suffix[j]
                if suffix[max(0, f - k)] < new[0]:
                    new[0] = suffix[max(0, f - k)]
                dp = new
            if dp[0] < best:
                best = dp[0]
        return best

