def solve(n, a):
    if n % 2 == 0:
        s = sorted(a)
        h = n // 2
        return sum(s[h:]) - sum(s[:h])
    def seq_vals(arr):
        # returns dict: even k -> sum top k/2 - sum bottom k/2 for prefix arr[:k]
        low = []; high = []; sl = 0; sh = 0
        res = [0] * (len(arr) + 1)
        for i, x in enumerate(arr):
            heapq.heappush(low, -x); sl += x
            t = -heapq.heappop(low); sl -= t
            heapq.heappush(high, t); sh += t
            if len(high) > len(low):
                u = heapq.heappop(high); sh -= u
                heapq.heappush(low, -u); sl += u
            k = i + 1
            if k % 2 == 0:
                res[k] = sh - sl
        return res
    pre = seq_vals(a)
    suf_rev = seq_vals(a[::-1])  # suf_rev[k] = value for last k elements
    best = 0
    for p in range(0, n, 2):
        q = n - 1 - p
        best = max(best, pre[p] + suf_rev[q])
    return best

