class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        MASK = (1 << 1001) - 1
        S = [1] * n  # bitset of achievable subset sums
        def ok():
            for i in range(n):
                if not (S[i] >> nums[i]) & 1:
                    return False
            return True
        if ok():
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                S[i] = (S[i] | (S[i] << v)) & MASK
            if ok():
                return k + 1
        return -1

