import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        is_p = [True] * LIM
        is_p[0] = is_p[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if is_p[i]:
                for j in range(i * i, LIM, i):
                    is_p[j] = False
        if is_p[n] or is_p[m]:
            return -1
        k = len(str(n))
        if len(str(m)) != k:
            return -1
        pw = [10 ** (k - 1 - i) for i in range(k)]

        def digits(x):
            return [(x // pw[i]) % 10 for i in range(k)]

        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, x = heapq.heappop(pq)
            if d != dist.get(x, INF):
                continue
            if x == m:
                return d
            ds = digits(x)
            for i in range(k):
                p = pw[i]
                di = ds[i]
                for nd in (di + 1, di - 1):
                    if 0 <= nd <= 9:
                        y = x + (nd - di) * p
                        if is_p[y]:
                            continue
                        nd2 = d + y
                        if nd2 < dist.get(y, INF):
                            dist[y] = nd2
                            heapq.heappush(pq, (nd2, y))
        return -1

