class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source); m = len(pattern)
        tgt = [False]*n
        for x in targetIndices:
            tgt[x] = True
        NEG = -10**9
        st = [NEG]*(m+1)
        st[0] = 0
        G = 0
        pos = {}
        for j in range(m, 0, -1):
            pos.setdefault(pattern[j-1], []).append(j)
        for i in range(n):
            t = 1 if tgt[i] else 0
            if t:
                G += 1
            ch = source[i]
            lst = pos.get(ch)
            if lst:
                lo = m - (n - 1 - i)
                for j in lst:
                    if j > i + 1 or j < lo:
                        continue
                    a = st[j]
                    b = st[j-1] - t
                    st[j] = a if a > b else b
        res = st[m] + G
        return max(res, 0) if st[m] > NEG // 2 else 0

