from collections import deque
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        def ok(W):
            seen = [False] * n
            seen[0] = True
            dq = deque([0])
            cnt = 1
            while dq:
                v = dq.popleft()
                for u, w in radj[v]:
                    if w <= W and not seen[u]:
                        seen[u] = True
                        cnt += 1
                        dq.append(u)
            return cnt == n
        ws = sorted(set(w for _, _, w in edges))
        if not ws or not ok(ws[-1]):
            return -1
        lo, hi = 0, len(ws) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(ws[mid]):
                hi = mid
            else:
                lo = mid + 1
        return ws[lo]

